@Composable
fun FixedBottomBar(
    progression:   List<ChordEvent>,
    chordName:     String,
    statusMessage: String?,
    onAddBar:      () -> Unit,
    onRemoveBar:   (ChordEvent) -> Unit,
    onClear:       () -> Unit
) {
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .background(Color(0xFF16161A))
            .border(1.dp, BORDER,
                RoundedCornerShape(topStart = 8.dp, topEnd = 8.dp))
    ) {
        if (progression.isNotEmpty()) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .background(RACK)
                    .padding(vertical = 6.dp),
                verticalAlignment = Alignment.CenterVertically
            ) {
                LazyRow(
                    modifier = Modifier.weight(1f),
                    contentPadding = PaddingValues(horizontal = 8.dp),
                    horizontalArrangement = Arrangement.spacedBy(4.dp)
                ) {
                    items(progression) { bar ->
                        ProgressionChip(bar = bar, onRemove = { onRemoveBar(bar) })
                    }
                }
                Box(
                    modifier = Modifier
                        .padding(end = 8.dp)
                        .clip(RoundedCornerShape(4.dp))
                        .background(Color(0xFF2A1A1A))
                        .border(1.dp, ACCENT, RoundedCornerShape(4.dp))
                        .clickable(onClick = onClear)
                        .padding(horizontal = 10.dp, vertical = 6.dp)
                ) {
                    Text("CLR", color = ACCENT, fontSize = 11.sp,
                        fontWeight = FontWeight.Bold,
                        fontFamily = FontFamily.Monospace)
                }
            }
        }
        statusMessage?.let { msg ->
            Text(
                text = msg, color = ACCENT2, fontSize = 11.sp,
                fontFamily = FontFamily.Monospace,
                modifier = Modifier.padding(horizontal = 12.dp, vertical = 2.dp)
            )
        }
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 12.dp, vertical = 8.dp)
                .clip(RoundedCornerShape(4.dp))
                .background(ACCENT)
                .clickable(onClick = onAddBar)
                .padding(vertical = 14.dp),
            contentAlignment = Alignment.Center
        ) {
            Text(
                text = "+ ADD BAR  ${chordName.uppercase()}",
                color = Color.White, fontSize = 14.sp,
                fontWeight = FontWeight.Bold,
                fontFamily = FontFamily.Monospace, letterSpacing = 1.sp
            )
        }
    }
}

@Composable
fun ProgressionChip(bar: ChordEvent, onRemove: () -> Unit) {
    Row(
        modifier = Modifier
            .clip(RoundedCornerShape(4.dp))
            .background(PANEL)
            .border(1.dp, BORDER, RoundedCornerShape(4.dp))
            .padding(start = 8.dp, end = 4.dp, top = 4.dp, bottom = 4.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(4.dp)
    ) {
        Text("${bar.barIndex + 1}", color = ACCENT2, fontSize = 10.sp,
            fontFamily = FontFamily.Monospace)
        Text(bar.chordName.uppercase(), color = TEXT, fontSize = 11.sp,
            fontWeight = FontWeight.Bold, fontFamily = FontFamily.Monospace,
            maxLines = 1)
        Box(
            modifier = Modifier
                .size(18.dp)
                .clip(RoundedCornerShape(2.dp))
                .background(Color(0xFF3A1A1A))
                .clickable(onClick = onRemove),
            contentAlignment = Alignment.Center
        ) {
            Text("x", color = ACCENT, fontSize = 10.sp,
                fontFamily = FontFamily.Monospace, fontWeight = FontWeight.Bold)
        }
    }
}

